import boto3
from botocore.exceptions import ClientError

def sync_prefix(src_bucket, src_prefix, dst_bucket, dst_prefix):
    s3 = boto3.client("s3")
    paginator = s3.get_paginator("list_objects_v2")
    copied, skipped = 0, 0
    for page in paginator.paginate(Bucket=src_bucket, Prefix=src_prefix):
        for obj in page.get("Contents", []):
            key = obj["Key"]
            rel = key[len(src_prefix):].lstrip("/")
            dst_key = f"{dst_prefix.rstrip('/')}/{rel}"
            if _same_size(s3, dst_bucket, dst_key, obj["Size"]):
                skipped += 1
                continue
            s3.copy({"Bucket": src_bucket, "Key": key}, dst_bucket, dst_key)
            copied += 1
    return {"copied": copied, "skipped": skipped}

def _same_size(s3, bucket, key, size):
    try:
        head = s3.head_object(Bucket=bucket, Key=key)
        return head["ContentLength"] == size
    except ClientError as e:
        if e.response["Error"]["Code"] in ("404", "NoSuchKey"):
            return False
        raise

import boto3

def purge_prefix(bucket: str, prefix: str) -> int:
    s3 = boto3.client("s3")
    paginator = s3.get_paginator("list_object_versions")
    deleted = 0
    for page in paginator.paginate(Bucket=bucket, Prefix=prefix):
        objects = []
        for v in page.get("Versions", []):
            objects.append({"Key": v["Key"], "VersionId": v["VersionId"]})
        for m in page.get("DeleteMarkers", []):
            objects.append({"Key": m["Key"], "VersionId": m["VersionId"]})
        # delete_objects handles up to 1000 keys per request
        for i in range(0, len(objects), 1000):
            batch = objects[i:i + 1000]
            resp = s3.delete_objects(
                Bucket=bucket,
                Delete={"Objects": batch, "Quiet": True},
            )
            deleted += len(batch) - len(resp.get("Errors", []))
            if resp.get("Errors"):
                raise RuntimeError(f"Delete errors: {resp['Errors']}")
    return deleted
